// The venue catalog, presets/catalog.json, parsed once at the build's boundary. The file is
// generated by `npm run catalog` from src/venue-catalog.ts; this schema mirrors that module's
// exported interfaces, and the order of its entries is kept as the file gives it. A catalog that
// does not match throws, naming the path that is wrong, so the build fails instead of the page
// rendering a hole. Pure: the page reads the file.

import * as R from "remeda";
import { z } from "zod";

const FILE = "presets/catalog.json";

const fail = (what: string): never => {
  throw new Error(`site: ${FILE} ${what}`);
};

const kindSchema = z.strictObject({
  kind: z.string().min(1),
  pagesMax: z.number().int().positive().nullable(),
  bodyPagesMax: z.number().int().positive().nullable(),
  refPagesMax: z.number().int().positive().nullable(),
});

const editionSchema = z.strictObject({
  id: z.string().min(1),
  series: z.string().min(1),
  year: z.number().int(),
  family: z.string().min(1),
  templateLabel: z.string().min(1),
  blind: z.boolean(),
  kinds: z.array(kindSchema).readonly(),
});

const conferenceSchema = editionSchema.extend({
  workshops: z.array(editionSchema).readonly(),
});

/** src/domain/venue-field.ts › VENUE_FIELDS; a field the site does not know fails the build. */
const fieldSchema = z.strictObject({
  field: z.enum(["software-engineering", "security", "nlp", "ml-ai"]),
  title: z.string().min(1),
  conferences: z.array(conferenceSchema).readonly(),
});

const familySchema = z.strictObject({
  id: z.string().min(1),
  templateLabel: z.string().min(1),
  anyConferenceOf: z.string().min(1).nullable(),
});

const catalogSchema = z.strictObject({
  fields: z.array(fieldSchema).readonly(),
  families: z.array(familySchema).readonly(),
});

export type CatalogKind = Readonly<z.infer<typeof kindSchema>>;
export type CatalogEdition = Readonly<z.infer<typeof editionSchema>>;
export type CatalogConference = Readonly<z.infer<typeof conferenceSchema>>;
export type CatalogField = Readonly<z.infer<typeof fieldSchema>>;
export type VenueCatalog = Readonly<z.infer<typeof catalogSchema>>;

const json = (text: string): unknown => {
  try {
    return JSON.parse(text) as unknown;
  } catch (error) {
    return fail(`is not JSON: ${String(error)}`);
  }
};

/** presets/catalog.json's text as a catalog; throws, naming each wrong path, when it is not one. */
export const parseCatalog = (text: string): VenueCatalog => {
  const parsed = catalogSchema.safeParse(json(text));
  return parsed.success
    ? parsed.data
    : fail(
        `is not a venue catalog: ${parsed.error.issues
          .map((i) => `${i.path.join(".")}: ${i.message}`)
          .join("; ")}`,
      );
};

/** The organisations whose template alone is a preset («ACM»), once each, in catalog order. */
export const anyConferenceOf = (catalog: VenueCatalog): readonly string[] => {
  const orgs = R.unique(
    catalog.families.flatMap((f) =>
      f.anyConferenceOf === null ? [] : [f.anyConferenceOf],
    ),
  );
  return orgs.length > 0 ? orgs : fail("has no family for any conference");
};

/** How many editions the grid holds: each conference and each workshop held at one. */
export const venueCount = (catalog: VenueCatalog): number =>
  R.sumBy(
    catalog.fields.flatMap((f) => f.conferences),
    (c) => 1 + c.workshops.length,
  );

/** «AGENT 2027». */
export const editionName = (e: CatalogEdition): string =>
  `${e.series} ${String(e.year)}`;

/** «ACM, IEEE or ACL». */
export const orList = (names: readonly string[]): string =>
  names.length < 2
    ? names.join("")
    : `${names.slice(0, -1).join(", ")} or ${names.slice(-1).join("")}`;
